// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract Recorder {
    bytes public lastData;
    uint256 public calls;

    fallback() external payable {
        lastData = msg.data;
        calls += 1;
    }
}

contract InvMutTest is Test {
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function testFuzz_property(bytes memory data) public {
        Recorder rec = new Recorder();
        bool ok; try c.forward(address(rec), data) { ok = true; } catch { ok = false; }
        assertTrue(ok && rec.calls() == 1 && keccak256(rec.lastData()) == keccak256(data));
    }
}
